def parse_json_secret(secret_id: str, project_id: str = None) -> dict:
    if project_id is None:
        project_id = os.getenv("GCP_PROJECT_ID")
    if not project_id:
        raise ValueError("GCP_PROJECT_ID not provided and not found in environment variables.")

